(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["pl"] = {"ui":{"skip":"Przejdź do treści","back":"← Wróć do AI-gile","lang.button":"Język: {name}","lang.dialog":"Wybierz język","lang.search":"Szukaj języków","lang.none":"Nie znaleziono języka","lang.notYet":"{name} nie jest jeszcze przetłumaczony","theme.aria":"Przełącz między jasnym a ciemnym motywem","theme.toLight":"Przełącz na jasny motyw","theme.toDark":"Przełącz na ciemny motyw","index.title":"AI-gile: Twój zespół AI do programowania, na jednej tablicy","index.description":"AI-gile to tablica kanban dla zespołów programistycznych AI. Pracują, gdy Ty śpisz; Ty dostajesz jeden krótki stos spraw do rozstrzygnięcia, przetestowania i zaakceptowania.","hero.logoAlt":"Ikona tablicy AI-gile","hero.h1.html":"Twój zespół AI do programowania, na jednej&nbsp;tablicy.","hero.alpha":"🐣 Zamknięta pre-alfa","hero.alphaTitle":"Wczesna i niedokończona: dzięki, że próbujesz!","hero.lede":"Budują, gdy śpisz. Budzisz się przy jednym krótkim stosie: kilka pytań, kilka rzeczy do przetestowania, fioletowy diament czy dwa. Klik, akceptacja i z powrotem do kawy.","dl.windows":"Aplikacja na Windows","dl.browser":"Uruchom w przeglądarce","dl.soon":"Wkrótce","dl.notify":"🔔 Powiadom mnie, gdy ruszy","dl.notifySmall":"Alfa lub beta","hero.secondary":"Agile, ale zespół nigdy nie potrzebuje kawy na stojąco. (I tak robią stand-upy.)","pitch.h2":"AI-gile w tylu słowach, ilu chcesz","pitch.lede":"Wybierz długość, od jednego słowa do 144. Każda długość to osobny opis, napisany właśnie na ten rozmiar. Przeciągnij suwak albo użyj strzałek.","pitch.rangeLabel":"Długość w słowach","pitch.dice":"🎲 inna wersja","pitch.words.one":"{n} słowo","pitch.words.few":"{n} słowa","pitch.words.many":"{n} słów","pitch.words.other":"{n} słowa","pitch.letters.one":"{n} litera","pitch.letters.few":"{n} litery","pitch.letters.many":"{n} liter","pitch.letters.other":"{n} litery","pitch.chars.one":"{n} znak","pitch.chars.few":"{n} znaki","pitch.chars.many":"{n} znaków","pitch.chars.other":"{n} znaku","count.line.html.one":"{n} karta na tablicy w tej chwili","count.line.html.few":"{n} karty na tablicy w tej chwili","count.line.html.many":"{n} kart na tablicy w tej chwili","count.line.html.other":"{n} karty na tablicy w tej chwili","features.aria":"Co robi","f.pile.h":"Jeden stos dla Ciebie","f.pile.html":"<b>Dla Ciebie</b> zbiera wszystko, co czeka na Ciebie, we wszystkich projektach: pytania, rzeczy do przetestowania, zadania tylko dla człowieka. Twoja kolejka mówi, co dalej i ile to zajmie.","f.sleep.h":"Zespoły, które pracują, gdy śpisz","f.sleep.p":"Każdy projekt ma lidera i zespół agentów AI. Skomentuj kartę, a zespół się budzi, robi swoje i oddaje ją z krokami, które zrozumie zmęczony człowiek.","f.tester.h":"Najpierw sprawdza tester AI","f.tester.p":"Zanim cokolwiek do Ciebie trafi, tester wykonuje kroki w kopii aplikacji i pokazuje, co zobaczył, ze zrzutem ekranu. Przejrzyj te, które przeszły, i zaakceptuj jednym kliknięciem.","f.proof.h":"Dowody, nie obietnice","f.proof.p":"Każde przekazanie pokazuje, co się zmieniło: pliki, diff, zrzuty ekranu. Bez otwierania każdej aplikacji, żeby sprawdzić, czy już gotowe.","f.chat.h":"Rozmawiaj ze swoimi liderami","f.chat.p":"Pasek w stylu Discorda: jedna ikona na projekt, fioletowe diamenty przy tym, co czeka na Ciebie. Napisz do lidera pomysł; zamieni go w karty i plan, z przyciskiem ✅ Go.","f.tidy.h":"Sam dba o porządek","f.tidy.p":"Powiązane karty zlewają się w jedną, zagmatwane tytuły są poprawiane, a kontrola tokenów utrzymuje kod szczupłym. Mniej rzeczy do przełączania, mniej do myślenia.","f.private.h":"Twoje, na Twoim komputerze","f.private.li1":"Tablica działa na Twojej własnej maszynie i odpowiada tylko Tobie.","f.private.li2":"Prywatne wiadomości między ludźmi są szyfrowane od końca do końca.","f.private.li3":"Bez kont, bez trackerów, bez ciasteczek.","f.lang.h":"W Twoim języku","f.lang.p":"Ponad 120 języków, od niderlandzkiego, walijskiego i japońskiego po piracki, Yodę i klingoński, z szybkim przełącznikiem na angielski dla słów programistycznych.","tl.aria":"Oś czasu od pierwszej rozmowy do planów","tl.h2":"Od pierwszej rozmowy do tego, co dalej","tl.lede":"Prawdziwe daty i godziny, w Twojej strefie czasowej. Po dzisiejszym dniu to plan, bez obiecywanych dat.","tl.today":"Dziś","tl.planned":"w planach","tl.cards.one":"{n} karta","tl.cards.few":"{n} karty","tl.cards.many":"{n} kart","tl.cards.other":"{n} karty","join.h2":"Dołącz","join.lede":"AI-gile budują mały człowiek i bardzo wielu cierpliwych agentów. Na razie jest prywatne, w zamkniętej alfie z przyjaciółmi. Chcesz spróbować, gdy się otworzy?","join.btn":"Zgłoś zainteresowanie","join.small":"Napiszemy do Ciebie e-mailem i nic więcej","footer.tag":"AI-gile. Bez trackerów, bez ciasteczek, bez kawy na stojąco.","footer.licence":"Licencja biznesowa","footer.status":"Status","form.sending":"Wysyłanie…","form.failed":"Nie udało się: spróbuj ponownie później.","form.offline":"Nie można połączyć się z AI-gile: spróbuj ponownie później.","interest.title":"AI-gile: powiadom mnie, gdy ruszy alfa","interest.description":"Zostaw e-mail, żeby dowiedzieć się, kiedy ruszy zamknięta alfa lub beta AI-gile.","interest.h1":"🔔 Powiadom mnie, gdy ruszy","interest.lede":"AI-gile jest w zamkniętej pre-alfie. Zostaw e-mail, a napiszemy raz, gdy znajdzie się dla Ciebie miejsce.","interest.email":"Twój e-mail","interest.which":"Który test?","interest.alpha":"Zamknięta alfa: wcześnie, surowo, dużo zmian","interest.beta":"Beta: spokojniej, później","interest.both":"Obojętnie, co pierwsze","interest.submit":"Zapisz mnie na listę","interest.thanks":"Dzięki! Jesteś na liście.","licence.title":"AI-gile: licencja biznesowa","licence.description":"Używasz AI-gile w firmie? Poproś o bezpłatną licencję biznesową.","licence.h1":"📜 Licencja biznesowa","licence.lede":"Używasz AI-gile w pracy? Napisz, kim jesteś i czym się zajmujesz. Jeśli robi to coś dobrego, licencja jest bezpłatna.","licence.company":"Firma","licence.website":"Strona internetowa","licence.what":"Czym się zajmujesz","licence.how":"Jak to pomaga światu","licence.email":"E-mail","licence.submit":"Wyślij wniosek","licence.thanks":"Dzięki! Odpowiemy e-mailem.","status.title":"Status AI-gile","status.h1":"Status AI-gile","status.quiet":"Wszystko spokojnie","status.checking":"Sprawdzanie…","status.offline":"Nie można teraz połączyć się z usługą statusu (ponawiam)","status.updated":"zaktualizowano {ago}","status.justNow":"przed chwilą","status.min":"{n} min temu","status.hours":"{n} godz. temu","status.days":"{n} dni temu","live.h2":"Zobacz, jak to powstaje, na żywo","live.caption":"Każda karta jest ukryta: widzisz kształt pracy, a nie słowa.","live.watching.one":"na żywo: ogląda {n}","live.watching.other":"na żywo: oglądają {n}","live.offline":"Tablica na żywo bierze krótki oddech. Zajrzyj wkrótce ponownie.","live.cols":"Backlog|Do zrobienia|W toku|Zespół sprawdza|Do przetestowania przez Ciebie|Dla zespołu|Gotowe","live.last.now":"Ostatnia karta przesunięta przed chwilą","live.last.min.one":"Ostatnia karta przesunięta {n} min temu","live.last.min.other":"Ostatnia karta przesunięta {n} min temu","live.last.hour.one":"Ostatnia karta przesunięta {n} godz. temu","live.last.hour.other":"Ostatnia karta przesunięta {n} godz. temu","live.last.day.one":"Ostatnia karta przesunięta {n} dzień temu","live.last.day.other":"Ostatnia karta przesunięta {n} dni temu"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboty.","Zlecone."]},{"n":2,"texts":["Kanban robotów.","Agenci, uporządkowani.","Pomysły, zbudowane."]},{"n":3,"texts":["Kanban dla robotów.","Pomysły stają się funkcjami.","Darmowy kanban agentów."]},{"n":5,"texts":["Tablica kanban prowadzona przez agentów.","Ty piszesz karty. Agenci budują.","Darmowe, lokalne, testowane, odrobinę zwariowane."]},{"n":8,"texts":["Darmowy kanban, w którym pracują agenci AI.","Zapisz pomysł. Agenci go zbudują. Ty akceptujesz.","Agile dla jednego człowieka i wielu cierpliwych robotów."]},{"n":13,"texts":["Tablica kanban na Twoim komputerze, gdzie karty biorą agenci AI.","Zapisz swój pomysł na karcie. Cały zespół agentów go zbuduje, a tester AI sprawdzi, czy działa.","Za darmo, bez kont, bez trackerów: tablica, trochę robotów i Ty u steru."]},{"n":21,"texts":["AI-gile to tablica kanban do pracy z agentami programistycznymi AI. Oni biorą karty; Ty testujesz i akceptujesz.","Każdy projekt dostaje lidera i zespół agentów AI. Skomentuj dowolną kartę, a zespół bierze się do pracy.","Darmowa, osobista tablica zadań, która działa na Twoim własnym komputerze, bez żadnych kont. Pracują roboty, ale to Ty decydujesz, co jest gotowe."]},{"n":34,"texts":["Wrzucasz pomysły na tablicę. Zespół agentów AI zamienia je w działające funkcje, testuje i oddaje z krokami do wypróbowania. Nic nie liczy się jako zrobione, dopóki Ty tego nie powiesz.","AI-gile to domowa tablica kanban, którą Rich zbudował przy ogromnej pomocy agentów, którymi teraz zarządza. Jest darmowa, działa na Twoim komputerze i jest dzielona z przyjaciółmi, a nie sprzedawana.","Wyobraź sobie zwykłą tablicę kanban z kolumnami od Backlogu do Gotowe, tyle że karty biorą agenci AI. Zgłaszają postępy, pytają, gdy utkną, i zawsze czekają na Twój kciuk w górę."]},{"n":55,"texts":["AI-gile to tablica kanban, na której zespół składa się z agentów AI. Każdy projekt ma lidera, który planuje pracę, i pomocników, którzy ją wykonują. Gdy funkcja jest gotowa, tester AI ją wypróbowuje i robi zrzut ekranu, a potem trafia na Twój stos. Zaakceptuj ją albo skomentuj, a oni poprawią.","Zaczęło się jako sposób jednej osoby na ogarnięcie wielu sesji programowania z AI naraz, a urosło do prawdziwej tablicy. Działa na Twojej maszynie, nie wymaga konta i nie ma trackerów. Jest darmowa dla przyjaciół i ciekawskich. Jest też niedokończona, więc spodziewaj się chropowatości i od czasu do czasu niespodzianki.","Powiedzmy sobie szczerze. Pomysły nadal musisz mieć sam i wyniki nadal musisz sprawdzać. AI-gile robi wszystko pomiędzy: trzyma karty w porządku, budzi właściwego agenta, gdy napiszesz komentarz, pokazuje dokładnie, co się zmieniło, i zbiera całą resztę w jeden krótki stos, który czeka właśnie na Ciebie."]},{"n":89,"texts":["AI-gile to darmowa tablica kanban, którą uruchamiasz na własnym komputerze. Zamiast ludzi każdy projekt ma zespół agentów AI: lidera, który zamienia Twoje pomysły w karty i plan, oraz pomocników, którzy biorą karty według priorytetu. Gdy coś jest zbudowane, tester AI wykonuje kroki testowe i pokazuje, co zobaczył. Potem całość czeka na jednym stosie zwanym Dla Ciebie. Akceptujesz albo komentujesz, a zespół próbuje jeszcze raz. Nic nie trafia do Gotowe bez Ciebie.","Kilka rzeczy, których możesz się nie spodziewać. Nocna straż uzupełnia kolumnę Do zrobienia, gdy śpisz, wybierając karty, które nie potrzebują Twojej odpowiedzi. Licznik tokenów pokazuje, ile agenci zużyli dziś i w tym tygodniu, a Tryb bez tokenów każe im przestać wydawać. Możesz pisać do przyjaciół, a prywatne wiadomości są szyfrowane od końca do końca. Tablica mówi w około 120 językach, w tym po niderlandzku, flamandzku, piracku i klingońsku. Nic z tego nie kosztuje ani grosza i nikt nie chce Ci tego sprzedać.","AI-gile to mały, osobisty projekt, a nie firma. Rich chciał opiekować się kilkoma projektami z AI bez otwierania każdej aplikacji osobno, żeby zobaczyć, co słychać, więc razem z agentami zbudował do tego tablicę, a potem tą samą tablicą zbudował resztę jej samej. Jest w zamkniętej pre-alfie, czyli działa, przeważnie, dla garstki przyjaciół. Nie ma cennika, newslettera ani planu podbijania świata. Jeśli brzmi to przydatnie, poproś o dostęp, gdy otworzy się trochę szerzej."]},{"n":144,"texts":["AI-gile to tablica kanban dla jednego człowieka i bardzo wielu agentów AI. Działa na Twoim własnym komputerze i jest całkowicie darmowa. Dodajesz projekty, a każdy projekt dostaje lidera i mały zespół. Rozmawiasz z liderem, trochę jak na Discordzie, i opisujesz swój pomysł; lider zamienia go w karty i plan, po czym czeka, aż naciśniesz Go. Zespół przechodzi przez karty według priorytetu, korzystając z prostego wiersza poleceń stworzonego dla modeli językowych. Zanim cokolwiek wróci do Ciebie, tester AI wykonuje wszystkie kroki w kopii aplikacji i dołącza zrzut ekranu tego, co zobaczył. Gotowa praca ląduje na Twoim stosie razem ze zmienionymi plikami i diffem. Akceptujesz ją albo zostawiasz komentarz, a wtedy zespół się budzi i próbuje jeszcze raz. Tylko Ty możesz przenieść kartę do kolumny Gotowe, nikt inny i nigdy.","Dzień z AI-gile, mniej więcej. Wieczorem zostawiasz kilka komentarzy: ten przycisk jest w złym miejscu, tamta lista powinna być posortowana, a czy mógłby być tryb ciemny. Idziesz spać. Agenci czytają komentarze, wprowadzają zmiany, testują je i oddają Ci wyniki. Jeśli kolumna Do zrobienia się opróżni, nocna straż uzupełnia ją kartami z backlogu, które nie potrzebują Twojej odpowiedzi. Rano czeka jeden krótki stos: kilka pytań i kilka rzeczy do wypróbowania, każda z krokami, za którymi trafi nawet niewyspana osoba, i ze zrzutem ekranu działającej wersji. Przeklikujesz wszystko, akceptujesz to, co dobre, i odsyłasz resztę. Licznik tokenów pokazuje, ile to wszystko zużyło, a Tryb bez tokenów czeka na chudsze tygodnie. Potem jesz śniadanie, w czym agenci jeszcze Ci nie pomogą.","Najpierw to, czym AI-gile nie jest. Nie jest startupem, nie jest na sprzedaż i nikt nie zbiera Twoich danych. To darmowa tablica, która działa na Twoim komputerze, bez kont, bez trackerów i bez ciasteczek. A czym jest: jednym uporządkowanym miejscem, w którym widzisz wszystkie projekty z AI naraz, z zespołem agentów robiącym karty i Tobą podejmującym decyzje. Łączy powiązane karty, poprawia zagmatwane tytuły i pilnuje, żeby kod pozostał szczupły. Mówi w około 120 językach, od niderlandzkiego i flamandzkiego po piracki i klingoński. Przyjaciele mogą do siebie pisać, prywatnie i szyfrowanie. Zbudowali ją Rich i bardzo wielu cierpliwych agentów, głównie korzystając z niej samej. Jest w zamkniętej pre-alfie, więc w niektórych miejscach bywa surowa. Jeśli brzmi to zabawnie, poproś ładnie, a może wejdziesz wcześniej."]}],"quips":{"1":"Jedno słowo. Odważnie. Może za odważnie.","3":"Trzy słowa. Już szczerzej niż większość stron produktów.","8":"Osiem słów. Nadal krócej niż stand-up.","21":"Długości to zresztą story pointy. Oczywiście, że tak.","55":"Pięćdziesiąt pięć słów. Dwie karty skończyły się, gdy to czytasz.","144":"To ta długa. Nie ma 233. Agenci poszli spać."}},"timeline":{"first-idea.name":"Pierwszy pomysł","first-idea.line":"Najpierwsza rozmowa, zanim powstała choćby linijka kodu.","first-board.name":"Pierwsza tablica","first-board.line":"Tablica, która śledzi własną budowę: karty, kolumny, przeciąganie, projekty.","team-roles.name":"Zespół i role","team-roles.line":"Profile agentów, szablony zespołów, przestrzenie i kto za co odpowiada.","install.name":"Instalacja i wydania","install.line":"Zip, który przyjaciel zainstaluje, z samoaktualizacją, kanałami i cofaniem.","usage-saver.name":"Oszczędzanie zużycia","usage-saver.line":"Mierzenie kosztu uruchomień, szczupły kod, oszczędzanie limitu.","friends.name":"Przyjaciele i udostępnianie","friends.line":"Prywatne wiadomości, zaszyfrowany przekaźnik, zaproszenia, role i wspólne projekty.","languages.name":"Języki","languages.line":"Każdy tekst na ekranie w pliku językowym, na początek niderlandzki i flamandzki.","ai-tester.name":"Tester AI","ai-tester.line":"Tester sprawdza każde przekazanie jako pierwszy i pokazuje, co zobaczył.","website.name":"Strona internetowa","website.line":"aigile.lol, strona zapowiedzi i ta oś czasu.","streaming.name":"Czat i streaming","streaming.line":"Discord, Twitch, OBS, tryb streamera, GIF-y i emoji.","no-ai.name":"Wersja bez AI","no-ai.line":"Tablica dla ludzi, którzy programują bez AI, oraz tablice publiczne.","night-watch.name":"Nocna straż","night-watch.line":"Stróż i Scrum Master pilnują zespołów, gdy śpisz.","p-more.name":"Cała reszta","p-more.line":"Mniejsze pomysły, które wciąż czekają na swoją kolej.","p-android.name":"Telefon i Android","p-android.line":"Dostęp do tablicy z telefonu, a potem natywna aplikacja na Androida.","p-release.name":"Alfa i dalej","p-release.line":"Zamknięta alfa, strona na żywo, potem beta.","p-languages.name":"Więcej języków","p-languages.line":"Ponad sto języków i tryb immersji dla uczących się.","p-engines.name":"Więcej silników AI","p-engines.line":"Wybierz Claude, Codex lub Gemini dla każdego agenta.","p-pro.name":"Praktyka zawodowa","p-pro.line":"Etykiety ryzyka, bramki scalania, karty incydentów i bariery ochronne.","p-self.name":"Dbanie o Ciebie","p-self.line":"Tryb zmęczenia, przypomnienia o dbaniu o siebie i 4:20.","p-servers.name":"Serwery i skala","p-servers.line":"Globalne ustawienia serwera, role i planowanie wzrostu.","p-livestream.name":"Dodatki do streamów","p-livestream.line":"Czat Twitcha, własne emoji i publiczny podgląd na żywo."}};
